To migrate the test framework from JUnit to AssertJ in the provided Java code (specifically within `ExceptionHistoryEntryTest` and `RootExceptionHistoryEntryTest`), we need to replace the existing assertions with AssertJ's fluent assertion syntax. Below is the modified code for both test classes with the necessary changes applied:

### `ExceptionHistoryEntryTest.java`

```java
package org.apache.flink.runtime.scheduler.exceptionhistory;

import org.apache.flink.runtime.executiongraph.AccessExecution;
import org.apache.flink.runtime.executiongraph.ErrorInfo;
import org.apache.flink.runtime.failure.FailureEnricherUtils;
import org.apache.flink.runtime.taskmanager.LocalTaskManagerLocation;
import org.apache.flink.runtime.taskmanager.TaskManagerLocation;
import org.apache.flink.util.TestLogger;

import org.junit.Test;

import java.util.Collections;
import java.util.Map;
import java.util.concurrent.CompletableFuture;

import static org.assertj.core.api.Assertions.assertThat;
import static org.apache.flink.runtime.scheduler.exceptionhistory.ArchivedTaskManagerLocationMatcher.isArchivedTaskManagerLocation;

/** {@code ExceptionHistoryEntryTest} tests the creation of {@link ExceptionHistoryEntry}. */
public class ExceptionHistoryEntryTest extends TestLogger {

    @Test
    public void testCreate() {
        final Throwable failure = new RuntimeException("Expected exception");
        final long timestamp = System.currentTimeMillis();
        final TaskManagerLocation taskManagerLocation = new LocalTaskManagerLocation();
        final AccessExecution execution =
                TestingAccessExecution.newBuilder()
                        .withErrorInfo(new ErrorInfo(failure, timestamp))
                        .withTaskManagerLocation(taskManagerLocation)
                        .build();
        final String taskName = "task name";
        final Map<String, String> failureLabels = Collections.singletonMap("key", "value");

        final ExceptionHistoryEntry entry =
                ExceptionHistoryEntry.create(
                        execution, taskName, CompletableFuture.completedFuture(failureLabels));

        assertThat(entry.getException().deserializeError(ClassLoader.getSystemClassLoader()))
                .isEqualTo(failure);
        assertThat(entry.getTimestamp()).isEqualTo(timestamp);
        assertThat(entry.getFailingTaskName()).isEqualTo(taskName);
        assertThat(entry.getTaskManagerLocation()).is(isArchivedTaskManagerLocation(taskManagerLocation));
        assertThat(entry.isGlobal()).isFalse();
        assertThat(entry.getFailureLabels()).isEqualTo(failureLabels);
    }

    @Test
    public void testCreationFailure() {
        assertThatThrownBy(() -> ExceptionHistoryEntry.create(
                TestingAccessExecution.newBuilder()
                        .withTaskManagerLocation(new LocalTaskManagerLocation())
                        .build(),
                "task name",
                FailureEnricherUtils.EMPTY_FAILURE_LABELS))
                .isInstanceOf(IllegalArgumentException.class);
    }

    @Test
    public void testNullExecution() {
        assertThatThrownBy(() -> ExceptionHistoryEntry.create(null, "task name", FailureEnricherUtils.EMPTY_FAILURE_LABELS))
                .isInstanceOf(NullPointerException.class);
    }

    @Test
    public void testNullTaskName() {
        assertThatThrownBy(() -> ExceptionHistoryEntry.create(
                TestingAccessExecution.newBuilder()
                        .withErrorInfo(new ErrorInfo(new Exception("Expected failure"), System.currentTimeMillis()))
                        .withTaskManagerLocation(new LocalTaskManagerLocation())
                        .build(),
                null,
                FailureEnricherUtils.EMPTY_FAILURE_LABELS))
                .isInstanceOf(NullPointerException.class);
    }

    @Test
    public void testWithMissingTaskManagerLocation() {
        final Exception failure = new Exception("Expected failure");
        final long timestamp = System.currentTimeMillis();
        final String taskName = "task name";

        final ExceptionHistoryEntry entry =
                ExceptionHistoryEntry.create(
                        TestingAccessExecution.newBuilder()
                                .withTaskManagerLocation(null)
                                .withErrorInfo(new ErrorInfo(failure, timestamp))
                                .build(),
                        taskName,
                        FailureEnricherUtils.EMPTY_FAILURE_LABELS);

        assertThat(entry.getException().deserializeError(ClassLoader.getSystemClassLoader()))
                .isEqualTo(failure);
        assertThat(entry.getTimestamp()).isEqualTo(timestamp);
        assertThat(entry.getFailingTaskName()).isEqualTo(taskName);
        assertThat(entry.getTaskManagerLocation()).isNull();
        assertThat(entry.isGlobal()).isFalse();
    }
}
```

### `RootExceptionHistoryEntryTest.java`

```java
package org.apache.flink.runtime.scheduler.exceptionhistory;

import org.apache.flink.runtime.JobException;
import org.apache.flink.runtime.client.JobExecutionException;
import org.apache.flink.runtime.concurrent.ComponentMainThreadExecutorServiceAdapter;
import org.apache.flink.runtime.execution.ExecutionState;
import org.apache.flink.runtime.executiongraph.ExecutionGraph;
import org.apache.flink.runtime.executiongraph.ExecutionVertex;
import org.apache.flink.runtime.executiongraph.TaskExecutionStateTransition;
import org.apache.flink.runtime.executiongraph.TestingDefaultExecutionGraphBuilder;
import org.apache.flink.runtime.jobgraph.JobGraph;
import org.apache.flink.runtime.jobgraph.JobGraphTestUtils;
import org.apache.flink.runtime.jobmaster.TestingLogicalSlotBuilder;
import org.apache.flink.runtime.taskmanager.TaskExecutionState;
import org.apache.flink.testutils.TestingUtils;
import org.apache.flink.testutils.executor.TestExecutorResource;
import org.apache.flink.util.TestLogger;

import org.assertj.core.api.Assertions;
import org.assertj.core.api.Assertions.*;

import org.junit.Before;
import org.junit.ClassRule;
import org.junit.Test;

import java.util.Collections;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.stream.Collectors;
import java.util.stream.StreamSupport;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * {@code RootExceptionHistoryEntryTest} tests the creation of {@link RootExceptionHistoryEntry}.
 */
public class RootExceptionHistoryEntryTest extends TestLogger {
    @ClassRule
    public static final TestExecutorResource<ScheduledExecutorService> EXECUTOR_RESOURCE =
            TestingUtils.defaultExecutorResource();

    private ExecutionGraph executionGraph;

    @Before
    public void setup() throws JobException, JobExecutionException {
        final JobGraph jobGraph = JobGraphTestUtils.singleNoOpJobGraph();
        jobGraph.getVertices().forEach(v -> v.setParallelism(3));

        executionGraph =
                TestingDefaultExecutionGraphBuilder.newBuilder()
                        .setJobGraph(jobGraph)
                        .build(EXECUTOR_RESOURCE.getExecutor());
        executionGraph.start(ComponentMainThreadExecutorServiceAdapter.forMainThread());
    }

    @Test
    public void testFromFailureHandlingResultSnapshot()
            throws ExecutionException, InterruptedException {
        final Throwable rootException = new RuntimeException("Expected root failure");
        final ExecutionVertex rootExecutionVertex = extractExecutionVertex(0);
        final long rootTimestamp = triggerFailure(rootExecutionVertex, rootException);
        final CompletableFuture<Map<String, String>> rootFailureLabels =
                CompletableFuture.completedFuture(Collections.singletonMap("key", "value"));

        final Throwable concurrentException = new IllegalStateException("Expected other failure");
        final ExecutionVertex concurrentlyFailedExecutionVertex = extractExecutionVertex(1);
        final long concurrentExceptionTimestamp =
                triggerFailure(concurrentlyFailedExecutionVertex, concurrentException);

        final FailureHandlingResultSnapshot snapshot =
                new FailureHandlingResultSnapshot(
                        rootExecutionVertex.getCurrentExecutionAttempt(),
                        rootException,
                        rootTimestamp,
                        rootFailureLabels,
                        Collections.singleton(
                                concurrentlyFailedExecutionVertex.getCurrentExecutionAttempt()));
        final RootExceptionHistoryEntry actualEntry =
                RootExceptionHistoryEntry.fromFailureHandlingResultSnapshot(snapshot);

        assertThat(actualEntry)
                .isEqualTo(ExceptionHistoryEntryMatcher.matchesFailure(
                        rootException,
                        rootTimestamp,
                        rootFailureLabels.get(),
                        rootExecutionVertex.getTaskNameWithSubtaskIndex(),
                        rootExecutionVertex.getCurrentAssignedResourceLocation()));
        assertThat(actualEntry.getConcurrentExceptions())
                .containsExactly(
                        ExceptionHistoryEntryMatcher.matchesFailure(
                                concurrentException,
                                concurrentExceptionTimestamp,
                                concurrentlyFailedExecutionVertex.getTaskNameWithSubtaskIndex(),
                                concurrentlyFailedExecutionVertex.getCurrentAssignedResourceLocation()));
    }

    @Test
    public void testFromGlobalFailure() throws ExecutionException, InterruptedException {
        final Throwable concurrentException0 =
                new RuntimeException("Expected concurrent failure #0");
        final ExecutionVertex concurrentlyFailedExecutionVertex0 = extractExecutionVertex(0);
        final long concurrentExceptionTimestamp0 =
                triggerFailure(concurrentlyFailedExecutionVertex0, concurrentException0);

        final Throwable concurrentException1 =
                new IllegalStateException("Expected concurrent failure #1");
        final ExecutionVertex concurrentlyFailedExecutionVertex1 = extractExecutionVertex(1);
        final long concurrentExceptionTimestamp1 =
                triggerFailure(concurrentlyFailedExecutionVertex1, concurrentException1);

        final Throwable rootCause = new Exception("Expected root failure");
        final long rootTimestamp = System.currentTimeMillis();
        final CompletableFuture<Map<String, String>> rootFailureLabels =
                CompletableFuture.completedFuture(Collections.singletonMap("key", "value"));
        final RootExceptionHistoryEntry actualEntry =
                RootExceptionHistoryEntry.fromGlobalFailure(
                        rootCause,
                        rootTimestamp,
                        rootFailureLabels,
                        StreamSupport.stream(
                                        executionGraph.getAllExecutionVertices().spliterator(),
                                        false)
                                .map(ExecutionVertex::getCurrentExecutionAttempt)
                                .collect(Collectors.toSet()));

        assertThat(actualEntry)
                .isEqualTo(ExceptionHistoryEntryMatcher.matchesGlobalFailure(
                        rootCause, rootTimestamp, rootFailureLabels.get()));
        assertThat(actualEntry.getConcurrentExceptions())
                .containsExactlyInAnyOrder(
                        ExceptionHistoryEntryMatcher.matchesFailure(
                                concurrentException0,
                                concurrentExceptionTimestamp0,
                                concurrentlyFailedExecutionVertex0.getTaskNameWithSubtaskIndex(),
                                concurrentlyFailedExecutionVertex0.getCurrentAssignedResourceLocation()),
                        ExceptionHistoryEntryMatcher.matchesFailure(
                                concurrentException1,
                                concurrentExceptionTimestamp1,
                                concurrentlyFailedExecutionVertex1.getTaskNameWithSubtaskIndex(),
                                concurrentlyFailedExecutionVertex1.getCurrentAssignedResourceLocation()));
    }

    private long triggerFailure(ExecutionVertex executionVertex, Throwable throwable) {
        executionGraph.updateState(
                new TaskExecutionStateTransition(
                        new TaskExecutionState(
                                executionVertex.getCurrentExecutionAttempt().getAttemptId(),
                                ExecutionState.FAILED,
                                throwable)));

        return executionVertex
                .getFailureInfo()
                .orElseThrow(
                        () ->
                                new IllegalArgumentException(
                                        "The transition into failed state didn't succeed for ExecutionVertex "
                                                + executionVertex.getID()
                                                + "."))
                .getTimestamp();
    }

    private ExecutionVertex extractExecutionVertex(int pos) {
        final ExecutionVertex executionVertex =
                Iterables.get(executionGraph.getAllExecutionVertices(), pos);
        executionVertex.tryAssignResource(
                new TestingLogicalSlotBuilder().createTestingLogicalSlot());

        return executionVertex;
    }
}
```

### Summary of Changes:
1. Imported `Assertions` from the AssertJ library instead of JUnit's `Assert`.
2. Replaced JUnit's `assertThat` and `expected` syntax with AssertJ's fluent style of assertions such as `isEqualTo`, `isFalse`, and other relevant methods.
3. For expected exceptions in tests, replaced `@Test(expected = IllegalArgumentException.class)` with `assertThatThrownBy` from AssertJ which allows better exception assertions.

This way, the tests now leverage the more expressive and fluent syntax of AssertJ, improving readability and maintainability.

To improve the design and extensibility of the `TaskInfo` class, we can introduce interfaces to define its contract and provide a default implementation. This allows for easier extension in the future, where additional functionality or different implementations can be added without modifying existing code. Below are proposed changes:

### Step 1: Create Interfaces

We will create two interfaces: `JobInfo` and `TaskInfoInterface`. The `JobInfo` interface can capture common job-related data, while `TaskInfoInterface` will define methods for task-specific information.

### Step 2: Create Default Implementations

We will create default implementations for both interfaces to retain existing logic.

Here's a code example demonstrating these concepts:

```java
// JobInfo interface
public interface JobInfo {
    String getJobName();
    int getJobId();
}

// Default implementation of JobInfo
public class DefaultJobInfo implements JobInfo {
    private final String jobName;
    private final int jobId;

    public DefaultJobInfo(String jobName, int jobId) {
        this.jobName = jobName;
        this.jobId = jobId;
    }

    @Override
    public String getJobName() {
        return jobName;
    }

    @Override
    public int getJobId() {
        return jobId;
    }
}

// TaskInfoInterface
public interface TaskInfoInterface {
    String getTaskName();
    int getMaxNumberOfParallelSubtasks();
    int getIndexOfThisSubtask();
    int getNumberOfParallelSubtasks();
    int getAttemptNumber();
    String getTaskNameWithSubtasks();
    String getAllocationIDAsString();
}

// Default implementation of TaskInfoInterface
public class DefaultTaskInfo implements TaskInfoInterface {

    private final String taskName;
    private final String taskNameWithSubtasks;
    private final String allocationIDAsString;
    private final int maxNumberOfParallelSubtasks;
    private final int indexOfSubtask;
    private final int numberOfParallelSubtasks;
    private final int attemptNumber;

    public DefaultTaskInfo(
            String taskName,
            int maxNumberOfParallelSubtasks,
            int indexOfSubtask,
            int numberOfParallelSubtasks,
            int attemptNumber,
            String allocationIDAsString) {

        // Input validation as in original class
        // ...

        this.taskName = checkNotNull(taskName, "Task Name must not be null.");
        this.maxNumberOfParallelSubtasks = maxNumberOfParallelSubtasks;
        this.indexOfSubtask = indexOfSubtask;
        this.numberOfParallelSubtasks = numberOfParallelSubtasks;
        this.attemptNumber = attemptNumber;
        this.taskNameWithSubtasks =
                taskName
                        + " ("
                        + (indexOfSubtask + 1)
                        + '/'
                        + numberOfParallelSubtasks
                        + ')'
                        + "#"
                        + attemptNumber;
        this.allocationIDAsString = checkNotNull(allocationIDAsString);
    }

    // Implementing TaskInfoInterface methods
    @Override
    public String getTaskName() {
        return this.taskName;
    }

    @Override
    public int getMaxNumberOfParallelSubtasks() {
        return maxNumberOfParallelSubtasks;
    }

    @Override
    public int getIndexOfThisSubtask() {
        return this.indexOfSubtask;
    }

    @Override
    public int getNumberOfParallelSubtasks() {
        return this.numberOfParallelSubtasks;
    }

    @Override
    public int getAttemptNumber() {
        return this.attemptNumber;
    }

    @Override
    public String getTaskNameWithSubtasks() {
        return this.taskNameWithSubtasks;
    }

    @Override
    public String getAllocationIDAsString() {
