                configuration.get(RestartStrategyOptions.RESTART_STRATEGY_EXPONENTIAL_DELAY_RESET_BACKOFF_THRESHOLD);
        double jitter =
                configuration.get(RestartStrategyOptions.RESTART_STRATEGY_EXPONENTIAL_DELAY_JITTER_FACTOR);
        return exponentialDelayRestart(
                initialBackoff,
                maxBackoff,
                backoffMultiplier,
                resetBackoffThreshold,
                jitter);
    }

    private static RestartStrategyConfiguration createFailureRateRestart(ReadableConfig configuration) {
        int maxFailures =
                configuration.get(RestartStrategyOptions.RESTART_STRATEGY_FAILURE_RATE_MAX_FAILURES_PER_INTERVAL);
        Duration failureRateInterval =
                configuration.get(RestartStrategyOptions.RESTART_STRATEGY_FAILURE_RATE_FAILURE_RATE_INTERVAL);
        Duration failureRateDelay =
                configuration.get(RestartStrategyOptions.RESTART_STRATEGY_FAILURE_RATE_DELAY);
        return failureRateRestart(maxFailures, failureRateInterval, failureRateDelay);
    }
