	 *
	 * @param program {@link Program}
	 * @param allowUntrusted boolean flag, true means analyzer can search untrusted symbol
	 * servers
	 */
	public static void setAllowUntrustedOption(Program program, boolean allowUntrusted) { // Updated method name
		PdbAnalyzerCommon.setAllowUntrustedOption(NAME, program, allowUntrusted); // Updated call
	}
}
